sys_script_client.script:
// globally declared
var int_risk =100;

function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') { 
	// signfica que ya hay un valor pre-cargado
	if(newValue != ''){
	//significa que esta cargando
		g_form.showFieldMsg('impact','The newValue detected is: '+ newValue);
	}
	else{
	// significa que se quiere cambiar a un valor vacio
		g_form.showFieldMsg('impact','newValue detected as Null');
		return;
	}
   }
   else {
	g_form.showFieldMsg('impact','The newValue detected is: '+ newValue);
   }

   // Calls the Script Include
   var ga_InhRisk = new GlideAjax('x_1834695_risk_a_0.update_inhRisk');

   // We first call the method first
   ga_InhRisk.addParam('sysparm_name','updateInhRisk');

   // Declares the value of the necesary params
   ga_InhRisk.addParam('impact',g_form.getValue('impact'));
   ga_InhRisk.addParam('likelihood', g_form.getValue('likelihood'));
   ga_InhRisk.getXML(getResponse);
   // XMLWait() is not supported on Local Scope apps, Global apps are welcome

	// Service Now opens another thread to manage synchronusly the rest of the code
	function getResponse(response){
		// delete int_risk is not necesary
		int_risk = response; 
		// ^ response is an int, so there should be NO issue
		// ITS RETURNING LIKE AN OCJ
		g_form.showFieldMsg('impact',"The value int_RISK has been updated to:" + JSON.stringify(response));

		// Here we convert the int value to a string so that we can update the Inh_Risk 
		ga_InhRisk = new GlideAjax('x_1834695_risk_a_0.update_inhRisk');
		ga_InhRisk.addParam('sysparm_name','getInhRiskString');
		ga_InhRisk.addParam('intInhRisk',int_risk);

		ga_InhRisk.getXMLAnswer(function(response){
			var res = JSON.parse(response);
			g_form.showFieldMsg('impact','The text value of your inh_risk is:'+JSON.stringify(res));//test result
		});
	}
   // This part outside of the code will run besides the function up there
	// XML?? // gets the 'inh_risk' value as number
	//	g_form.showFieldMsg('impact',"The value inside int_risk:" + int_risk); 

	// Here we convert the int value to a string so that we can update the Inh_Risk 
	// ga_InhRisk = new GlideAjax('x_1834695_risk_a_0.update_inhRisk');
	// ga_InhRisk.addParam('sysparm_name','getInhRiskString');
	// ga_InhRisk.addParam('intInhRisk',int_risk);
	// var inhRisk = ga_InhRisk.getXMLAnswer(function(response){
	// 	var res = JSON.parse(response);
	// 	g_form.showFieldMsg('impact','The text value of your inh_risk is:'+JSON.stringify(res));//test result
	// });

	//Here we set the new value for inh_risk
	// g_form.setValue('inh_risk',inhRisk);

}
